window.kbPageData["views/entry/k-cc957239a51160c0"] = {"key":"entry/k-cc957239a51160c0","state":{"route":"entry/k-cc957239a51160c0"},"node":{"id":"k-cc957239a51160c0","mode":"k","title":"逆否命题","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["充分条件命题与其逆否命题等价"],"qs":["江苏 2025 C类 行测#93"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"公开回忆版保留相同措辞和标点。需核对正式试卷、勘误或命题说明是否明确规定条件（3）的前件为“未同时在三处停靠”。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：若丙班车不在行政楼、教学楼和图书馆停靠，则仅有乙班车在宿舍楼停靠","review":{"definition":"原题引文：若丙班车不在行政楼、教学楼和图书馆停靠，则仅有乙班车在宿舍楼停靠","explanation":"本题共有9次停靠，校门口最少且各点最多2趟，所以校门口1趟，其余各2趟。由此可否定“仅有乙班车在宿舍楼停靠”。若条件（3）的前件是“丙未同时在三处停靠”，逆否可推出丙在三处都停靠，宿舍楼两趟就是甲、乙，对应C。若读作“丙在三处都不停靠”，逆否只推出丙至少在其中一处停靠。例如甲停校门口、行政楼、教学楼，乙停教学楼、图书馆、宿舍楼，丙停行政楼、图书馆、宿舍楼，就满足该读法下的各项条件，宿舍楼停靠的是乙、丙。","references":[{"source":"web-c724397a3a8ab268","location":"第17页，第93题条件（3）","quote":"不在行政楼、教学楼和图书馆停靠"}],"evidence":"若丙班车不在行政楼、教学楼和图书馆停靠，则仅有乙班车在宿舍楼停靠","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 C类 行测#93":{"paper":"江苏 2025 C类 行测","n":93,"mod":"判断推理","src":["ffc394a1c160f331ec57.pdf",19],"asrc":["d1de3b437151c05b769e.pdf",27],"card":"e0f38f4af48bc6628c38e8f2","links":[{"id":"k-cc957239a51160c0","role":"解题依据","why":"否定条件（3）的后件后，可以推出其前件为假。"}]}},"terms":{},"references":{"web-c724397a3a8ab268":{"name":"星光公考《2025年江苏省公务员录用考试〈行测〉真题（C卷-考生回忆版）》","url":"https://upload.xingguanggongkao.com/pdf/2025%E5%B9%B4%E6%B1%9F%E8%8B%8F%E7%9C%81%E5%85%AC%E5%8A%A1%E5%91%98%E5%BD%95%E7%94%A8%E8%80%83%E8%AF%95%E3%80%8A%E8%A1%8C%E6%B5%8B%E3%80%8B%E7%9C%9F%E9%A2%98%EF%BC%88C%E5%8D%B7-%E8%80%83%E7%94%9F%E5%9B%9E%E5%BF%86%E7%89%88%EF%BC%89.pdf?time=1756887598"}},"topics":[],"units":{"k-cc957239a51160c0":[["江苏 2025 C类 行测#93"]]}};
